package ai.finsight.recurring;
import jakarta.persistence.*;import java.time.*;import java.util.UUID;
@Entity @Table(name="recurring_occurrence",uniqueConstraints=@UniqueConstraint(name="recurring_occurrence_idempotency",columnNames={"recurring_transaction_id","occurrence_date"}))
public class RecurringOccurrence{@Id private UUID id;@Column(name="user_id",nullable=false)private UUID userId;@Column(name="recurring_transaction_id",nullable=false)private UUID recurringTransactionId;@Column(name="occurrence_date",nullable=false)private LocalDate occurrenceDate;@Column(name="transaction_id")private UUID transactionId;@Column(name="created_at",nullable=false)private Instant createdAt;protected RecurringOccurrence(){}public RecurringOccurrence(UUID user,UUID recurrence,LocalDate date,UUID transaction){id=UUID.randomUUID();userId=user;recurringTransactionId=recurrence;occurrenceDate=date;transactionId=transaction;createdAt=Instant.now();}public UUID getUserId(){return userId;}public UUID getRecurringTransactionId(){return recurringTransactionId;}public LocalDate getOccurrenceDate(){return occurrenceDate;}public UUID getTransactionId(){return transactionId;}}
